const $=s=>document.querySelector(s), scene=$('#scene'), art=$('#scene-art'), copy=$('#copy'), speaker=$('#speaker'), chapter=$('#chapter'), actions=$('#actions');
const roster=['Nibbles','Timber','Spotty','Twiggy','Stripes','Noodles','Billy','Fipo','Gooby','Waddles','Sammy','Wally'];
let state={scene:'opening',popcorn:false,bongo:false,fredrick:false,sound:false};
try{state={...state,...JSON.parse(localStorage.getItem('tomi-adventure-v1'))}}catch(e){};
function save(){try{localStorage.setItem('tomi-adventure-v1',JSON.stringify(state))}catch(e){}}
function setText({c,s='Tomi',ch='A tiny mission',a=[]}){copy.innerHTML=c;speaker.textContent=s;chapter.textContent=ch;actions.innerHTML=a.map(x=>`<button class="${x.kind||'primary'}" data-action="${x.id}">${x.label}</button>`).join('');}
function collect(id,icon){$('#keep-'+id).textContent=icon;$('#keep-'+id).classList.add('collected')}
function render(){scene.className='scene '+state.scene;art.innerHTML='';if(state.popcorn)collect('popcorn','🍿');if(state.bongo&&state.fredrick){} if(state.scene==='opening')opening();if(state.scene==='circus')circus();if(state.scene==='portrait')portrait();if(state.scene==='concert')concert();if(state.scene==='ending')ending();save()}
function opening(){setText({c:'Hi!!! I have important anniversary business. We need three very good memories for the box.',a:[{id:'start',label:'Open the memory box'}]})}
function circus(){art.innerHTML=`<h2 class="scene-title">The circus<br>of enormous popcorn</h2><span class="worker">🎪</span><span class="popcorn ${state.popcorn?'spilled':''}">${state.popcorn?'🍿 🍿 🍿 🍿 🍿':'🍿'}</span>${!state.popcorn?'<button class="hotspot" data-action="spill" style="right:9%;bottom:20%">Tap the giant bag</button>':'<button class="hotspot" data-action="worker" style="left:8%;bottom:35%">Ask the kind worker</button>'}`;setText({ch:'Memory one · laughing together',c:state.popcorn?'The popcorn situation is now very serious. Maybe someone here can help?':'Tomi requires a circus souvenir. That bag seems… unusually large.',a:[{id:'helpCircus',label:'A little help',kind:'secondary'}]})}
function portrait(){const made=state.bongo&&state.fredrick;art.innerHTML=`<h2 class="scene-title" style="color:#313451">The little world<br>you made</h2><div class="friends">${roster.map(n=>`<span class="friend">${n}</span>`).join('')}${state.bongo?'<span class="friend">Bongo ✓</span>':''}${state.fredrick?'<span class="friend">Fredrick ✓</span>':''}</div><div class="cushion"></div><div class="curtain"></div><span class="party">✨</span>${!state.bongo?'<button class="hotspot" data-action="bongo" style="left:10%;bottom:18%;color:#47263a;border-color:#47263a">Behind cushion: Bongo?</button>':''}${!state.fredrick?'<button class="hotspot" data-action="fredrick" style="right:8%;bottom:20%;color:#fff;border-color:#fff">Turn off party light</button>':''}${made?'<button class="hotspot" data-action="tomiPortrait" style="left:39%;bottom:38%;color:#47263a;border-color:#47263a">Someone is missing…</button>':''}`;setText({ch:'Memory two · your little world',c:made?'Everyone is here. Tomi says a leader must check the group. Very carefully.':'Tomi has organized almost everyone. Two friends have misplaced themselves.',a:[{id:'helpPortrait',label:'Help Tomi',kind:'secondary'}]})}
function concert(){art.innerHTML=`<h2 class="scene-title">One ticket<br>back to fall</h2><button class="ticket" data-action="ticket">CONCERT<br>TICKET</button>`;setText({ch:'Memory three · remembering',c:'Tomi found an oversized ticket. It feels like it is holding another memory.',a:[{id:'ticket',label:'Look at the ticket'}]})}
function drive(step=0){scene.className='scene concert';art.innerHTML=`<div class="drive"><span class="leaf" style="left:10%;top:16%">🍂</span><span class="leaf" style="right:18%;top:27%;animation-delay:-1s">🍁</span><div class="mountains"></div><div class="car">🚗</div></div>`;const qs=[['Which season?',['Summer','Fall','Winter'],'Fall'],['Where were you headed?',['White Mountains','The beach','Downtown'],'White Mountains'],['Which date?',['First','Second','Fifth'],'Second']];if(step===3){collect('ticket','🎟');setText({ch:'Memory three · remembering',c:'A drive through nearly-peak fall color. A favorite song. A moment that mattered because it was remembered.<br><span class="hint">The personal words and concert photo can be added here when ready.</span>',a:[{id:'finishConcert',label:'Put the ticket in the box'}]});return}let q=qs[step];setText({ch:'Rebuild the drive',c:q[0]+`<div class="choices">${q[1].map(x=>`<button class="choice" data-choice="${x}" data-correct="${q[2]}" data-step="${step}">${x}</button>`).join('')}</div><span class="hint">Choose the memory Tomi is thinking of.</span>`,a:[{id:'helpDrive',label:'Help Tomi remember',kind:'secondary'}]})}
function ending(){collect('popcorn','🍿');collect('portrait','🖼');collect('ticket','🎟');art.innerHTML='<h2 class="scene-title">Mission complete.</h2><div class="reveal" style="position:absolute;left:12%;right:12%;bottom:16%">🍿 &nbsp; 🖼 &nbsp; 🎟<br><br><b>Tomi gives one very satisfied nod.</b></div>';setText({ch:'For Elsie',s:'Tomi',c:'The box is full. The memories are safe. There is one last thing inside the card for you.<br><br><b>Please open the handwritten letter.</b>',a:[{id:'replay',label:'Replay the adventure',kind:'secondary'}]})}
document.addEventListener('click',e=>{let a=e.target.dataset.action;if(a){if(a==='start'){state.scene='circus'}if(a==='spill'){state.popcorn=true;setText({ch:'Memory one · laughing together',c:'Oh. The popcorn has escaped. Tomi is considering the situation.',a:[{id:'worker',label:'Ask the friendly worker'}]})}if(a==='worker'||a==='helpCircus'){state.popcorn=true;collect('popcorn','🍿');state.scene='portrait'}if(a==='bongo'){state.bongo=true}if(a==='fredrick'){state.fredrick=true}if(a==='helpPortrait'){state.bongo=true;state.fredrick=true}if(a==='tomiPortrait'){collect('portrait','🖼');state.scene='concert'}if(a==='ticket'){drive(0);save();return}if(a==='helpDrive'){drive(3);save();return}if(a==='finishConcert'){state.scene='ending'}if(a==='replay'){state={scene:'opening',popcorn:false,bongo:false,fredrick:false,sound:state.sound};localStorage.removeItem('tomi-adventure-v1')}render();return}if(e.target.dataset.choice){let step=+e.target.dataset.step;if(e.target.dataset.choice===e.target.dataset.correct)drive(step+1);else copy.insertAdjacentHTML('beforeend','<p class="hint">Not quite — Tomi is still thinking.</p>')}});
$('#sound').addEventListener('click',()=>{state.sound=!state.sound;$('#sound').textContent='Sound: '+(state.sound?'on':'off');$('#sound').setAttribute('aria-pressed',state.sound);save()});$('#sound').textContent='Sound: '+(state.sound?'on':'off');render();
